// Authored Yogabase schedule facade test. This file is not generated by Microsoft Kiota.
//
// The shapes pinned here are the ones the mirrored client OpenAPI document declares for the schedule routes
// (x-yogabase-schedules and the four operations) and the product's gateway writes. The last tests hold each request
// the authored client sends to the request the generated Kiota builder builds for the same operation.
import assert from "node:assert/strict";
import test from "node:test";
import {
    YOGABASE_SCHEDULE_ERROR_CODES,
    YOGABASE_SCHEDULES_LIMITS,
    YOGABASE_STATUS_ERROR_CODES,
    YogabaseSchedulesClient,
    YogabaseSchedulesError,
} from "../dist/index.js";
import { authoredRequest, generatedRequest } from "./generatedRequests.mjs";

const PROJECT = "11111111-1111-4111-8111-111111111111";
const INSTANCE = "01234567-89ab-cdef-0123-456789abcdef";
const INSTANCE_HEX = "0123456789abcdef0123456789abcdef";
const ETAG3 = `"schedule-v3-${INSTANCE_HEX}"`;
const ITEM = `https://apps.example.test/v1/projects/${PROJECT}/schedules/nightly`;
const RUN = `${ITEM}/trigger`;
const INVOCATION = "9b9e2f3a-0d6e-4e6c-a4f1-2c6a7a5f0b11";

function fakeFetch(responses) {
    const calls = [];
    const fetcher = async (url, init) => {
        calls.push({ url: String(url), init });
        const next = responses.shift();
        if (typeof next === "function") return next(url, init);
        return next;
    };
    return { calls, fetcher };
}

function client(fake, options = {}) {
    return new YogabaseSchedulesClient({
        gatewayHost: "https://apps.example.test",
        projectId: PROJECT,
        accessToken: "user-token",
        fetch: fake.fetcher,
        ...options,
    });
}

function definition(overrides = {}) {
    return {
        scheduleId: "nightly",
        functionId: "orders-nightly",
        functionVersion: "1",
        cron: "*/5 * * * *",
        timeZone: "UTC",
        misfirePolicy: "SkipToNextOccurrence",
        concurrencyPolicy: "Allow",
        maxCatchUp: 1,
        maxAttempts: 3,
        deadlineSeconds: 300,
        payload: new TextEncoder().encode("hello"),
        ...overrides,
    };
}

function scheduleDocument(overrides = {}) {
    return {
        scheduleId: "nightly",
        projectId: PROJECT,
        subject: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
        functionId: "orders-nightly",
        functionVersion: "1",
        version: "3",
        instanceId: INSTANCE,
        lastOccurrence: "2026-10-03T05:00:00+00:00",
        oneShotAtUtc: null,
        ...overrides,
    };
}

function schedule(body, status = 200, etag = ETAG3) {
    const headers = { "Content-Type": "application/json" };
    if (etag !== undefined) headers.ETag = etag;
    return new Response(JSON.stringify(body), { status, headers });
}

function json(body, status = 200) {
    return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
}

// What ASP.NET Core writes for Results.Problem(statusCode, title, detail, extensions): the code and the limits
// are top-level members beside type, title, status and traceId. The schedule routes name a code only on the 413.
function problem(status, title, code, extras = {}) {
    const body = { type: "https://tools.ietf.org/html/rfc9110", title, status, traceId: "00-trace", ...extras };
    if (code !== undefined) body.code = code;
    return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/problem+json" } });
}

const REFUSED = new Set(["TypeError", "RangeError"]);
const refuses = error => REFUSED.has(error.name) || error instanceof RangeError || error instanceof TypeError;

// ------------------------------------------------------------------------------------------------
// Create and update
// ------------------------------------------------------------------------------------------------

test("create sends a conditional PUT of the exact body and reads the schedule and its ETag", async () => {
    const fake = fakeFetch([schedule(scheduleDocument({ version: "1" }), 201, `"schedule-v1-${INSTANCE_HEX}"`)]);
    const created = await client(fake).create(definition());

    const call = fake.calls[0];
    assert.equal(call.url, ITEM);
    assert.equal(call.init.method, "PUT");
    assert.equal(call.init.headers.get("Authorization"), "Bearer user-token");
    assert.equal(call.init.headers.get("Content-Type"), "application/json");
    assert.equal(call.init.redirect, "error");
    // Exactly one of the two preconditions: a create is conditional on there being nothing there.
    assert.equal(call.init.headers.get("If-None-Match"), "*");
    assert.equal(call.init.headers.has("If-Match"), false);
    // The names are the gateway's ScheduledLambdaDefinitionRequest, which refuses any other member.
    assert.equal(
        call.init.body,
        '{"scheduleId":"nightly","functionId":"orders-nightly","functionVersion":"1","cron":"*/5 * * * *","timeZone":"UTC",'
        + '"misfirePolicy":"SkipToNextOccurrence","concurrencyPolicy":"Allow","maxCatchUp":1,"maxAttempts":3,"deadlineSeconds":300,'
        + '"payloadBase64":"aGVsbG8="}',
    );
    assert.deepEqual(created, { ...scheduleDocument({ version: "1" }), eTag: `"schedule-v1-${INSTANCE_HEX}"` });
});

test("update sends the ETag as If-Match and never If-None-Match", async () => {
    const fake = fakeFetch([schedule(scheduleDocument({ version: "4" }), 200, `"schedule-v4-${INSTANCE_HEX}"`)]);
    const updated = await client(fake).update(definition(), ETAG3);

    assert.equal(fake.calls[0].url, ITEM);
    assert.equal(fake.calls[0].init.method, "PUT");
    assert.equal(fake.calls[0].init.headers.get("If-Match"), ETAG3);
    assert.equal(fake.calls[0].init.headers.has("If-None-Match"), false);
    assert.equal(updated.version, "4");
    assert.equal(updated.eTag, `"schedule-v4-${INSTANCE_HEX}"`);
});

test("a definition omits an absent or empty payload and sends a one-shot's instant in UTC", async () => {
    const fake = fakeFetch([schedule(scheduleDocument(), 201), schedule(scheduleDocument(), 201), schedule(scheduleDocument(), 201)]);
    const schedules = client(fake);
    await schedules.create(definition({ payload: undefined }));
    await schedules.create(definition({ payload: new Uint8Array(0) }));
    await schedules.create(definition({ payload: undefined, oneShotAtUtc: new Date("2026-10-03T12:00:00+09:00") }));

    const bodies = fake.calls.map(call => call.init.body);
    // A schedule with no payload and one with an empty payload are the same schedule to the gateway.
    assert.equal(bodies[0].includes("payloadBase64"), false);
    assert.equal(bodies[0], bodies[1]);
    assert.equal(bodies[0].includes("oneShotAtUtc"), false);
    // 12:00 at +09:00 is 03:00 UTC, and the gateway requires a UTC instant.
    assert.ok(bodies[2].endsWith(',"oneShotAtUtc":"2026-10-03T03:00:00.000Z"}'), bodies[2]);
});

test("every policy is sent by its name", async () => {
    const cases = [["RunImmediately", "Allow"], ["SkipToNextOccurrence", "Forbid"], ["RunAllMissed", "Replace"]];
    const fake = fakeFetch(cases.map(() => schedule(scheduleDocument(), 201)));
    const schedules = client(fake);
    for (const [misfirePolicy, concurrencyPolicy] of cases) {
        await schedules.create(definition({ misfirePolicy, concurrencyPolicy }));
    }
    assert.deepEqual(
        fake.calls.map(call => [JSON.parse(call.init.body).misfirePolicy, JSON.parse(call.init.body).concurrencyPolicy]),
        cases,
    );
});

test("a payload at exactly the inline limit is sent and one byte more is refused before the network", async () => {
    const fake = fakeFetch([schedule(scheduleDocument(), 201)]);
    const schedules = client(fake);
    await schedules.create(definition({ payload: new Uint8Array(YOGABASE_SCHEDULES_LIMITS.maximumPayloadBytes) }));
    assert.equal(JSON.parse(fake.calls[0].init.body).payloadBase64.length, 1_398_104);
    const over = definition({ payload: new Uint8Array(YOGABASE_SCHEDULES_LIMITS.maximumPayloadBytes + 1) });
    await assert.rejects(schedules.create(over), RangeError);
    await assert.rejects(schedules.update(over, ETAG3), RangeError);
    assert.equal(fake.calls.length, 1);
});

test("a malformed definition is refused before the network, on create and on update", async () => {
    const fake = fakeFetch([]);
    const schedules = client(fake);
    const long = (length, character = "x") => character.repeat(length);
    const cases = {
        "a blank schedule id": { scheduleId: "  " },
        "a padded schedule id": { scheduleId: " nightly" },
        "a schedule id with a control character": { scheduleId: "night\nly" },
        "a schedule id over 128 characters": { scheduleId: long(129) },
        "a schedule id of one dot": { scheduleId: "." },
        "a schedule id of two dots": { scheduleId: ".." },
        "a blank function id": { functionId: " " },
        "a function id over 256 characters": { functionId: long(257) },
        "a missing function version": { functionVersion: undefined },
        "a function version over 64 characters": { functionVersion: long(65) },
        "a blank cron": { cron: "" },
        "a cron over 128 characters": { cron: long(129, "1") },
        "a blank time zone": { timeZone: "" },
        "a time zone over 128 characters": { timeZone: long(129) },
        "no misfire policy": { misfirePolicy: undefined },
        "an unknown misfire policy": { misfirePolicy: "RunNever" },
        "no concurrency policy": { concurrencyPolicy: undefined },
        "an unknown concurrency policy": { concurrencyPolicy: "Queue" },
        "a catch-up of zero": { maxCatchUp: 0 },
        "a catch-up over 128": { maxCatchUp: 129 },
        "a fractional catch-up": { maxCatchUp: 1.5 },
        "no attempts": { maxAttempts: 0 },
        "attempts over 16": { maxAttempts: 17 },
        "a deadline of zero": { deadlineSeconds: 0 },
        "a deadline over a day": { deadlineSeconds: 86_401 },
        "a payload that is not bytes": { payload: "hello" },
        "an invalid one-shot instant": { oneShotAtUtc: "not a time" },
        "an invalid one-shot date": { oneShotAtUtc: new Date(Number.NaN) },
    };
    for (const [name, overrides] of Object.entries(cases)) {
        await assert.rejects(schedules.create(definition(overrides)), refuses, name);
        await assert.rejects(schedules.update(definition(overrides), ETAG3), refuses, name);
    }
    await assert.rejects(schedules.create(undefined), TypeError);
    await assert.rejects(schedules.update(undefined, ETAG3), TypeError);
    assert.equal(fake.calls.length, 0);
});

test("the longest accepted values of every bounded member are sent", async () => {
    const fake = fakeFetch([schedule(scheduleDocument({ scheduleId: "s".repeat(128) }), 201)]);
    await client(fake).create(definition({
        scheduleId: "s".repeat(128),
        functionId: "f".repeat(256),
        functionVersion: "v".repeat(64),
        cron: "1".repeat(128),
        timeZone: "z".repeat(128),
        maxCatchUp: 128,
        maxAttempts: 16,
        deadlineSeconds: 86_400,
    }));
    const body = JSON.parse(fake.calls[0].init.body);
    assert.equal(body.scheduleId.length, 128);
    assert.equal(body.functionId.length, 256);
    assert.equal(body.deadlineSeconds, 86_400);
});

test("a schedule id that needs escaping travels as one escaped path segment", async () => {
    const id = "weekly report/é?#";
    const fake = fakeFetch([schedule(scheduleDocument({ scheduleId: id }), 201), schedule(scheduleDocument({ scheduleId: id }))]);
    const schedules = client(fake);
    await schedules.create(definition({ scheduleId: id }));
    await schedules.get(id);
    const escaped = `https://apps.example.test/v1/projects/${PROJECT}/schedules/weekly%20report%2F%C3%A9%3F%23`;
    assert.deepEqual(fake.calls.map(call => call.url), [escaped, escaped]);
    // The id in the body is the id in the path, unescaped.
    assert.equal(JSON.parse(fake.calls[0].init.body).scheduleId, id);
});

// ------------------------------------------------------------------------------------------------
// The ETag a caller passes back
// ------------------------------------------------------------------------------------------------

test("an ETag that is not the gateway's token is refused before the network on every conditional call", async () => {
    const fake = fakeFetch([]);
    const schedules = client(fake);
    const request = { idempotencyKey: "run-1", deadline: new Date(Date.now() + 600_000) };
    const malformed = [
        "",
        "*",
        `schedule-v3-${INSTANCE_HEX}`,
        `W/"schedule-v3-${INSTANCE_HEX}"`,
        `"schedule-v3-${INSTANCE_HEX.toUpperCase()}"`,
        `"schedule-v3-${INSTANCE_HEX.slice(1)}"`,
        `"schedule-v3-${INSTANCE_HEX}0"`,
        `"schedule-v3-${INSTANCE}"`,
        `"schedule-v0-${INSTANCE_HEX}"`,
        `"schedule-v03-${INSTANCE_HEX}"`,
        `"schedule-v-${INSTANCE_HEX}"`,
        `"schedule-v9223372036854775808-${INSTANCE_HEX}"`,
        `"schedule-v3-${"0".repeat(32)}"`,
        `"v3-${INSTANCE_HEX}"`,
        `${ETAG3}, "schedule-v4-${INSTANCE_HEX}"`,
        undefined,
        null,
        3,
    ];
    for (const eTag of malformed) {
        const label = JSON.stringify(eTag);
        await assert.rejects(schedules.update(definition(), eTag), TypeError, label);
        await assert.rejects(schedules.delete("nightly", eTag), TypeError, label);
        await assert.rejects(schedules.trigger("nightly", eTag, request), TypeError, label);
    }
    assert.equal(fake.calls.length, 0);
});

test("the largest version that fits a 64-bit integer is an accepted ETag", async () => {
    const fake = fakeFetch([new Response(null, { status: 204 })]);
    const eTag = `"schedule-v9223372036854775807-${INSTANCE_HEX}"`;
    await client(fake).delete("nightly", eTag);
    assert.equal(fake.calls[0].init.headers.get("If-Match"), eTag);
});

// ------------------------------------------------------------------------------------------------
// Get
// ------------------------------------------------------------------------------------------------

test("get reads one schedule by its route and builds its ETag from the body", async () => {
    const fake = fakeFetch([schedule(scheduleDocument())]);
    const read = await client(fake).get("nightly");

    assert.equal(fake.calls[0].url, ITEM);
    assert.equal(fake.calls[0].init.method, "GET");
    assert.equal(fake.calls[0].init.headers.get("Authorization"), "Bearer user-token");
    assert.equal(fake.calls[0].init.body, undefined);
    assert.equal(fake.calls[0].init.headers.has("If-Match"), false);
    assert.equal(read.eTag, ETAG3);
    assert.equal(read.version, "3");
});

test("get maps a one-shot's instant and the null members of a recurring schedule", async () => {
    const fake = fakeFetch([
        schedule(scheduleDocument({ lastOccurrence: null, oneShotAtUtc: "2026-10-04T01:02:03+00:00" })),
        schedule(scheduleDocument()),
        schedule({ ...scheduleDocument(), lastOccurrence: undefined, oneShotAtUtc: undefined }),
    ]);
    const schedules = client(fake);
    const oneShot = await schedules.get("nightly");
    const recurring = await schedules.get("nightly");
    const absent = await schedules.get("nightly");

    assert.equal(oneShot.oneShotAtUtc, "2026-10-04T01:02:03+00:00");
    assert.equal(oneShot.lastOccurrence, null);
    assert.equal(recurring.oneShotAtUtc, null);
    assert.equal(recurring.lastOccurrence, "2026-10-03T05:00:00+00:00");
    // A member the gateway left out reads as null, as the contract makes both members nullable.
    assert.equal(absent.oneShotAtUtc, null);
    assert.equal(absent.lastOccurrence, null);
});

test("a strong ETag header that disagrees with the body is refused and a weak, repeated or missing one is ignored", async () => {
    const fake = fakeFetch([
        schedule(scheduleDocument(), 200, `"schedule-v4-${INSTANCE_HEX}"`),
        schedule(scheduleDocument(), 200, `"schedule-v3-${"f".repeat(32)}"`),
        schedule(scheduleDocument(), 200, `W/"schedule-v9-${INSTANCE_HEX}"`),
        schedule(scheduleDocument(), 200, `${ETAG3}, "schedule-v4-${INSTANCE_HEX}"`),
        schedule(scheduleDocument(), 200, undefined),
        schedule(scheduleDocument(), 200, ETAG3),
    ]);
    const schedules = client(fake);

    // Two strong headers that are not the body's token: the version is another, and so is the instance.
    for (let attempt = 0; attempt < 2; attempt += 1) {
        await assert.rejects(
            schedules.get("nightly"),
            error => error instanceof YogabaseSchedulesError && error.code === YOGABASE_SCHEDULE_ERROR_CODES.responseInvalid,
        );
    }
    // A proxy that compresses a response may weaken its ETag, and the body carries the same facts.
    for (let attempt = 0; attempt < 4; attempt += 1) {
        assert.equal((await schedules.get("nightly")).eTag, ETAG3);
    }
});

test("a schedule the gateway describes wrongly is refused, not guessed at", async () => {
    const wrong = {
        "another schedule": { scheduleId: "other" },
        "no schedule id": { scheduleId: undefined },
        "another project": { projectId: "33333333-3333-4333-8333-333333333333" },
        "a project that is not a uuid": { projectId: "not-a-uuid" },
        "an empty owner": { subject: "00000000-0000-0000-0000-000000000000" },
        "an owner that is not a uuid": { subject: "not-a-uuid" },
        "an empty function id": { functionId: "" },
        "no function version": { functionVersion: undefined },
        "a version of zero": { version: "0" },
        "a version with a leading zero": { version: "03" },
        "a version that is not a number": { version: "abc" },
        "a version over 64 bits": { version: "9223372036854775808" },
        "a version as a number": { version: 3 },
        "an empty instance": { instanceId: "00000000-0000-0000-0000-000000000000" },
        "an instance without hyphens": { instanceId: INSTANCE_HEX },
        "no instance": { instanceId: undefined },
        "a last occurrence that is not a time": { lastOccurrence: "yesterday" },
        "a one-shot instant that is not a time": { oneShotAtUtc: 12 },
    };
    const fake = fakeFetch(Object.values(wrong).map(overrides => schedule(scheduleDocument(overrides))));
    const schedules = client(fake);
    for (const name of Object.keys(wrong)) {
        await assert.rejects(
            schedules.get("nightly"),
            error => error instanceof YogabaseSchedulesError && error.status === 502 && error.code === YOGABASE_SCHEDULE_ERROR_CODES.responseInvalid,
            name,
        );
    }
});

test("an answer that is not a schedule document is refused", async () => {
    const fake = fakeFetch([json({ scheduleId: "nightly" }), json([]), json(null), new Response("not json", { status: 200 })]);
    const schedules = client(fake);
    for (let index = 0; index < 4; index += 1) {
        await assert.rejects(
            schedules.get("nightly"),
            error => error instanceof YogabaseSchedulesError && error.code === YOGABASE_SCHEDULE_ERROR_CODES.responseInvalid,
        );
    }
});

test("a member this client does not know is kept out of the schedule and does not refuse it", async () => {
    const fake = fakeFetch([schedule({ ...scheduleDocument(), extra: 1 })]);
    const read = await client(fake).get("nightly");
    assert.equal("extra" in read, false);
    assert.equal(read.scheduleId, "nightly");
});

