test("delete sends If-Match with no body and answers 204", async () => {
    const fake = fakeFetch([new Response(null, { status: 204 })]);
    const result = await client(fake).delete("nightly", ETAG3);

    assert.equal(result, undefined);
    assert.equal(fake.calls[0].url, ITEM);
    assert.equal(fake.calls[0].init.method, "DELETE");
    assert.equal(fake.calls[0].init.headers.get("If-Match"), ETAG3);
    assert.equal(fake.calls[0].init.body, undefined);
});

// ------------------------------------------------------------------------------------------------
// Trigger
// ------------------------------------------------------------------------------------------------

test("trigger sends the exact body with If-Match and reads both outcomes", async () => {
    const fake = fakeFetch([json({ outcome: 0, invocationId: INVOCATION }, 202), json({ outcome: 1, invocationId: INVOCATION }, 202)]);
    const schedules = client(fake);
    const request = { idempotencyKey: "run-1", deadline: new Date("2026-10-03T21:30:00+09:00") };
    const first = await schedules.trigger("nightly", ETAG3, request);
    const repeat = await schedules.trigger("nightly", ETAG3, request);

    assert.equal(fake.calls[0].url, RUN);
    assert.equal(fake.calls[0].init.method, "POST");
    assert.equal(fake.calls[0].init.headers.get("If-Match"), ETAG3);
    assert.equal(fake.calls[0].init.headers.has("If-None-Match"), false);
    // 21:30 at +09:00 is 12:30 UTC.
    assert.equal(fake.calls[0].init.body, '{"idempotencyKey":"run-1","deadline":"2026-10-03T12:30:00.000Z"}');
    assert.deepEqual(first, { outcome: "Enqueued", invocationId: INVOCATION });
    assert.deepEqual(repeat, { outcome: "Replayed", invocationId: INVOCATION });
});

test("a malformed run key or deadline is refused before the network and a key of the longest length is sent", async () => {
    const fake = fakeFetch([json({ outcome: 0, invocationId: INVOCATION }, 202)]);
    const schedules = client(fake);
    const deadline = new Date(Date.now() + 600_000);
    for (const idempotencyKey of ["", "   ", " padded", "padded ", "k".repeat(257), undefined, 5]) {
        await assert.rejects(schedules.trigger("nightly", ETAG3, { idempotencyKey, deadline }), refuses, String(idempotencyKey));
    }
    await assert.rejects(schedules.trigger("nightly", ETAG3, { idempotencyKey: "k", deadline: "soon" }), TypeError);
    await assert.rejects(schedules.trigger("nightly", ETAG3, { idempotencyKey: "k" }), TypeError);
    await assert.rejects(schedules.trigger("nightly", ETAG3, undefined), TypeError);
    assert.equal(fake.calls.length, 0);

    await schedules.trigger("nightly", ETAG3, { idempotencyKey: "k".repeat(256), deadline });
    assert.equal(JSON.parse(fake.calls[0].init.body).idempotencyKey.length, 256);
});

test("a run the gateway describes wrongly is refused", async () => {
    const wrong = [
        { outcome: 2, invocationId: INVOCATION },
        { outcome: -1, invocationId: INVOCATION },
        { invocationId: INVOCATION },
        { outcome: "0", invocationId: INVOCATION },
        { outcome: 0, invocationId: "00000000-0000-0000-0000-000000000000" },
        { outcome: 0, invocationId: "nope" },
        { outcome: 0 },
    ];
    const fake = fakeFetch(wrong.map(document => json(document, 202)));
    const schedules = client(fake);
    for (const document of wrong) {
        await assert.rejects(
            schedules.trigger("nightly", ETAG3, { idempotencyKey: "k", deadline: new Date(Date.now() + 600_000) }),
            error => error instanceof YogabaseSchedulesError && error.code === YOGABASE_SCHEDULE_ERROR_CODES.responseInvalid,
            JSON.stringify(document),
        );
    }
});

// ------------------------------------------------------------------------------------------------
// Refusals
// ------------------------------------------------------------------------------------------------

test("every refusal reads as its status where the gateway names no code", async () => {
    const codes = YOGABASE_STATUS_ERROR_CODES;
    const expectations = [
        [400, codes.requestFailed],
        [401, codes.authenticationRequired],
        [403, codes.forbidden],
        [404, codes.notFound],
        [409, codes.conflict],
        [412, codes.preconditionFailed],
        [415, codes.unsupportedMediaType],
        [428, codes.preconditionRequired],
        [429, codes.rateLimited],
        [503, codes.requestFailed],
    ];
    const bodiless = new Set([404, 409, 415]);
    const refusal = status => (bodiless.has(status) ? new Response(null, { status }) : problem(status, "Fixed title."));
    for (const [status, code] of expectations) {
        const calls = [
            client => client.update(definition(), ETAG3),
            client => client.delete("nightly", ETAG3),
            client => client.trigger("nightly", ETAG3, { idempotencyKey: "k", deadline: new Date(Date.now() + 600_000) }),
            client => client.get("nightly"),
        ];
        for (const call of calls) {
            await assert.rejects(
                call(client(fakeFetch([refusal(status)]))),
                error => error instanceof YogabaseSchedulesError && error.status === status && error.code === code
                    && error.limitBytes === undefined && error.maxBodyBytes === undefined,
                `${status}`,
            );
        }
    }
});

test("a refusal's title is its message and its trace reaches the error", async () => {
    const fake = fakeFetch([problem(412, "The schedule concurrency precondition is stale.")]);
    await assert.rejects(
        client(fake).update(definition(), ETAG3),
        error => error.message === "The schedule concurrency precondition is stale."
            && error.correlationId === "00-trace"
            && error.problem.title === error.message,
    );
});

test("a payload too large refusal names the code and both limits", async () => {
    const fake = fakeFetch([problem(413, "The schedule payload is too large.", "schedule_payload_too_large", {
        detail: "The request is larger than this route accepts. A schedule's payload may be at most 1048576 bytes before base64 encoding, and the whole request body at most 8394167 bytes.",
        limitBytes: 1_048_576,
        maxBodyBytes: 8_394_167,
    })]);
    await assert.rejects(
        client(fake).create(definition()),
        error => error instanceof YogabaseSchedulesError && error.status === 413 && error.code === "schedule_payload_too_large"
            && error.limitBytes === 1_048_576 && error.maxBodyBytes === 8_394_167 && /8394167/.test(error.message),
    );
});

test("a bare 413 from a gateway that predates the named refusal reads as payload_too_large", async () => {
    const fake = fakeFetch([new Response(null, { status: 413 })]);
    await assert.rejects(
        client(fake).create(definition()),
        error => error.status === 413 && error.code === "payload_too_large" && error.code !== YOGABASE_SCHEDULE_ERROR_CODES.payloadTooLarge
            && error.limitBytes === undefined,
    );
});

test("limits the refusal states badly are not trusted", async () => {
    const fake = fakeFetch([problem(413, "x", "schedule_payload_too_large", { limitBytes: -1, maxBodyBytes: "8394167" })]);
    await assert.rejects(
        client(fake).create(definition()),
        error => error.limitBytes === undefined && error.maxBodyBytes === undefined,
    );
});

test("an installation without the Scheduler answers a bare not_found on every route", async () => {
    const fake = fakeFetch([new Response(null, { status: 404 }), new Response(null, { status: 404 }), new Response(null, { status: 404 })]);
    const schedules = client(fake);
    for (const call of [
        () => schedules.get("nightly"),
        () => schedules.delete("nightly", ETAG3),
        () => schedules.trigger("nightly", ETAG3, { idempotencyKey: "k", deadline: new Date(Date.now() + 600_000) }),
    ]) {
        await assert.rejects(call(), error => error.status === 404 && error.code === YOGABASE_STATUS_ERROR_CODES.notFound);
    }
});

// ------------------------------------------------------------------------------------------------
// Scope: token, abort, options
// ------------------------------------------------------------------------------------------------

test("the access token provider is asked for each call, and an empty token is refused", async () => {
    let issued = 0;
    const fake = fakeFetch([schedule(scheduleDocument()), schedule(scheduleDocument())]);
    const schedules = client(fake, { accessToken: () => `token-${++issued}` });
    await schedules.get("nightly");
    await schedules.get("nightly");
    assert.deepEqual(fake.calls.map(call => call.init.headers.get("Authorization")), ["Bearer token-1", "Bearer token-2"]);

    const empty = client(fakeFetch([]), { accessToken: () => "" });
    await assert.rejects(empty.get("nightly"), TypeError);
});

test("an aborted signal stops a schedule call", async () => {
    const controller = new AbortController();
    controller.abort();
    const fake = fakeFetch([(url, init) => {
        if (init.signal?.aborted) throw Object.assign(new Error("aborted"), { name: "AbortError" });
        return schedule(scheduleDocument());
    }]);
    await assert.rejects(client(fake).get("nightly", { signal: controller.signal }), error => error.name === "AbortError");
});

test("the timeout stops a call that never answers", async () => {
    const hanging = (url, init) => new Promise((resolve, reject) => {
        init.signal?.addEventListener("abort", () => reject(init.signal.reason), { once: true });
    });
    await assert.rejects(
        client(fakeFetch([hanging]), { timeoutMs: 30 }).get("nightly"),
        error => /schedules request timed out/.test(error.message),
    );
});

test("the gateway host is an origin, https unless it is a loopback host that was allowed", () => {
    const base = { projectId: PROJECT, accessToken: "token" };
    assert.throws(() => new YogabaseSchedulesClient({ ...base, gatewayHost: "http://apps.example.test" }), TypeError);
    assert.throws(() => new YogabaseSchedulesClient({ ...base, gatewayHost: "https://apps.example.test/path" }), TypeError);
    assert.throws(() => new YogabaseSchedulesClient({ ...base, gatewayHost: "https://user:pw@apps.example.test" }), TypeError);
    assert.throws(() => new YogabaseSchedulesClient({ ...base, gatewayHost: "http://localhost:5080" }), TypeError);
    assert.equal(new YogabaseSchedulesClient({ ...base, gatewayHost: "http://localhost:5080", allowInsecureLoopback: true }).gatewayHost, "http://localhost:5080");
});

test("the project in the route is the client's own and a token is required", () => {
    const base = { gatewayHost: "https://apps.example.test", accessToken: "token" };
    assert.throws(() => new YogabaseSchedulesClient({ ...base, projectId: "not-a-guid" }), TypeError);
    assert.throws(() => new YogabaseSchedulesClient({ ...base, projectId: "00000000-0000-0000-0000-000000000000" }), TypeError);
    assert.throws(() => new YogabaseSchedulesClient({ ...base, projectId: PROJECT, accessToken: "" }), TypeError);
    assert.equal(new YogabaseSchedulesClient({ ...base, projectId: PROJECT }).projectId, PROJECT);
});

// ------------------------------------------------------------------------------------------------
// The authored requests are the generated builders' requests
// ------------------------------------------------------------------------------------------------

const generatedDefinition = () => ({
    scheduleId: "nightly",
    functionId: "orders-nightly",
    functionVersion: "1",
    cron: "*/5 * * * *",
    timeZone: "UTC",
    misfirePolicy: "SkipToNextOccurrence",
    concurrencyPolicy: "Allow",
    maxCatchUp: 1,
    maxAttempts: 3,
    deadlineSeconds: 300,
    payloadBase64: "aGVsbG8=",
});

const item = (api) => api.v1.projects.byProjectId(PROJECT).schedules.byScheduleId("nightly");

async function authored(call) {
    const fake = fakeFetch([() => new Response("{}", { status: 200 })]);
    try {
        await call(client(fake));
    } catch {
        // The canned answer is not a schedule; only the request is compared.
    }
    return authoredRequest(fake.calls[0]);
}

function assertSameRequest(sent, built, extraHeaders) {
    assert.equal(sent.url, built.url);
    assert.equal(sent.method, built.method);
    assert.deepEqual(sent.body, built.body);
    // The authored client accepts at least what the generated builder asks for.
    for (const accepted of built.headers.accept.split(",").map(part => part.trim())) {
        assert.ok(sent.headers.accept.split(",").map(part => part.trim()).includes(accepted), `${sent.headers.accept} accepts ${accepted}`);
    }
    for (const [name, value] of Object.entries(extraHeaders)) {
        assert.equal(sent.headers[name], value, name);
        assert.equal(built.headers[name], value, name);
    }
}

test("create and update send the request the generated put builder builds", async () => {
    const createBuilt = await generatedRequest(api => item(api).put(generatedDefinition(), { headers: { "If-None-Match": "*" } }));
    assertSameRequest(await authored(c => c.create(definition())), createBuilt, { "if-none-match": "*" });

    const updateBuilt = await generatedRequest(api => item(api).put(generatedDefinition(), { headers: { "If-Match": ETAG3 } }));
    assertSameRequest(await authored(c => c.update(definition(), ETAG3)), updateBuilt, { "if-match": ETAG3 });
});

test("a one-shot is sent the way the generated builder serialises its instant", async () => {
    const instant = new Date("2026-10-03T03:00:00.000Z");
    const built = await generatedRequest(api => item(api).put({ ...generatedDefinition(), oneShotAtUtc: instant }, { headers: { "If-None-Match": "*" } }));
    assertSameRequest(await authored(c => c.create(definition({ oneShotAtUtc: instant }))), built, { "if-none-match": "*" });
});

test("get, delete and trigger send the requests the generated builders build", async () => {
    assertSameRequest(await authored(c => c.get("nightly")), await generatedRequest(api => item(api).get()), {});

    const deleteBuilt = await generatedRequest(api => item(api).delete({ headers: { "If-Match": ETAG3 } }));
    assertSameRequest(await authored(c => c.delete("nightly", ETAG3)), deleteBuilt, { "if-match": ETAG3 });

    const deadline = new Date("2026-10-03T12:30:00.000Z");
    const triggerBuilt = await generatedRequest(api => item(api).trigger.post({ idempotencyKey: "run-1", deadline }, { headers: { "If-Match": ETAG3 } }));
    assertSameRequest(
        await authored(c => c.trigger("nightly", ETAG3, { idempotencyKey: "run-1", deadline })),
        triggerBuilt,
        { "if-match": ETAG3 },
    );
});

test("the generated builders and the authored client name the same members and the same bounds", async () => {
    // A member the generated model has and the authored definition lacks (or the reverse) would be a contract change
    // the authored client missed: compare the names the generated serializer writes with the ones sent.
    const built = await generatedRequest(api => item(api).put({ ...generatedDefinition(), oneShotAtUtc: new Date("2026-10-03T03:00:00.000Z") }, { headers: { "If-None-Match": "*" } }));
    const sent = await authored(c => c.create(definition({ oneShotAtUtc: new Date("2026-10-03T03:00:00.000Z") })));
    assert.deepEqual(Object.keys(sent.body).sort(), Object.keys(built.body).sort());
    assert.equal(YOGABASE_SCHEDULES_LIMITS.maximumPayloadBytes, 1_048_576);
});
